import FreeCAD
import Part

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

# Let's examine the circles in each sketch (these are likely the pad/hole features)
for sketch_name in ["Sketch001", "Sketch002"]:
    obj = doc.getObject(sketch_name)
    if obj:
        print(f"=== {sketch_name} ===")
